body['cyberfoundations']='''<section class="program-hero cf-hero"><img src="/assets/city.webp" alt="Original CyberFoundations City artwork with its six labeled districts"><div class="wrap"><span class="eyebrow">Tier I · 12-week program</span><h1>Welcome to<br><em>CyberFoundations City.</em></h1><p>Discover the systems. Follow the connections. Build the confidence to explain what you know.</p></div></section><section class="wrap section"><div class="section-head"><span class="eyebrow">Your learning journey</span><h2>Six districts.<br>A foundation that connects.</h2><p>The City gives technical concepts a place and a purpose. Explore the themes below; enrolled coursework remains in your CVI learning tools.</p></div><div class="district-grid">'''+''.join(item(f'0{i}',t,d) for i,(t,d) in enumerate([('Welcome Center','Get oriented, find your tools, and begin documenting your learning.'),('Foundry District','Explore hardware, operating systems, and the command line.'),('The Grid & Cloud Heights','Understand networking, troubleshooting, and cloud infrastructure.'),('Vault District','Explore cryptography, integrity, and digital trust.'),('City Hall & Registry','Connect security fundamentals with identity and access management.'),('Broadcast Tower','Bring your findings together through clear technical communication.')],1))+'''</div></section><section class="guides section"><div class="wrap"><div class="section-head"><span class="eyebrow">Meet your guides</span><h2>Familiar faces.<br>A clear way forward.</h2></div><div class="guide-grid"><article><img src="/assets/nova.webp" alt="Nova seated at a microphone in a CVI-branded studio" loading="lazy"><div><span class="eyebrow">Your welcoming guide</span><h3>Nova</h3><p>A familiar presence to help introduce the journey and connect each step to the bigger picture.</p></div></article><article><img src="/assets/ivy.webp" alt="Original Ivy character taking notes in the Foundry District" loading="lazy"><div><span class="eyebrow">Learning through the City</span><h3>Ivy</h3><p>Follow Ivy’s learning journey as technical ideas become practical skills, investigations, and decisions.</p></div></article></div></div></section><section class="wrap section split"><div><span class="eyebrow">Make your learning visible</span><h2>Build evidence<br>as you learn.</h2></div><div><p class="lead">Organize labs, notes, reflections, and projects in your own GitHub portfolio. Use the official template and your cohort’s instructions to begin.</p>'''+link(gh+'cyberfoundations-student-portfolio-template','Explore the portfolio template')+'''</div></section>'''
body['pki']='''<section class="program-hero pki-hero"><img src="/assets/pki.webp" alt="Original PKI hero artwork: gold certificate trust connections linking a blue technology city"><div class="wrap"><span class="eyebrow">Tier II · PKI Career Pathway</span><h1>Build the expertise<br>behind <em>digital trust.</em></h1><p>Explore the certificates, operations, and architecture that support trusted enterprise connections.</p></div></section><section class="wrap section"><div class="section-head"><span class="eyebrow">A progressive pathway</span><h2>From first principles<br>to enterprise decisions.</h2></div><div class="three-grid phases">'''+''.join(item(f'0{i}',t,d) for i,(t,d) in enumerate([('Foundations','Keys, hashing, signatures, certificate anatomy, formats, and trust chains.'),('Operations','Certificate issuance, revocation, health checks, recovery, and lifecycle management.'),('Architecture','Translate requirements into trust designs, analyze evidence, and communicate technical decisions.')],1))+'''</div></section><section class="manifesto"><div class="wrap split"><span class="eyebrow">Trust in practice</span><div><h2>Understand the chain.<br><em>Explain the decision.</em></h2><p>Build practical fluency through labs, troubleshooting, documentation, and architecture work. Connect each technical action to the trust it supports.</p></div></div></section><section class="wrap section"><div class="section-head"><span class="eyebrow">Your technical toolkit</span><h2>Start with the source.</h2></div><div class="two-grid">'''+resource('PKI lab resources','Explore the public CVI PKI lab repository. Follow your cohort’s guidance for assigned work.','pki-foundations-labs')+resource('PKI portfolio template','Organize lab evidence, notes, reflections, and projects in your own repository.','pki-student-portfolio-template')+'''</div></section>'''
body['projects']=intro('Applied technology','Learning, built into practice.','Explore CVI’s areas of technical work and the public resources that support them.')+'''<section class="wrap section top-less"><div class="feature-row"><span class="feature-number">01 / FOUNDATIONS</span><div><h2>Technical learning<br>with a place and a purpose.</h2><p>CyberFoundations City connects infrastructure, networking, cryptography, security, identity, and communication through a coherent learning environment.</p><a class="text-link" href="/cyberfoundations/">Explore CyberFoundations ↗</a></div></div><div class="feature-row"><span class="feature-number">02 / DIGITAL TRUST</span><div><h2>Practical PKI.<br>Documented reasoning.</h2><p>Certificate labs and portfolio structures support technical practice and clear explanations of results.</p><a class="text-link" href="/pki/">Explore PKI ↗</a></div><img src="/assets/pki.webp" alt="PKI trust city" loading="lazy"></div><div class="feature-row"><span class="feature-number">03 / TECHNICAL EVIDENCE</span><div><h2>Work you can<br>organize and explain.</h2><p>CVI’s public portfolio templates give learners a consistent structure for technical artifacts. Individual student work remains separate.</p><a class="text-link" href="/resources/">Find the templates ↗</a></div></div></section>'''
body['resources']=intro('The resource desk','Find your next step.','Official GitHub resources and guidance for navigating CVI’s learning ecosystem.')+'''<section class="wrap section top-less"><div class="resource-list">'''+resource('CVI GitHub Handbook','Start here for repository basics, template instructions, documentation standards, and academic integrity guidance.','cvi-cohort-handbook')+resource('CyberFoundations portfolio template','Create your own independent portfolio using “Use this template.” Follow cohort instructions for weekly submissions.','cyberfoundations-student-portfolio-template')+resource('PKI portfolio template','A structured starting point for PKI labs, notes, reflections, and projects.','pki-student-portfolio-template')+resource('PKI lab repository','Public instructional resources for the PKI pathway. Your cohort guidance determines assigned work.','pki-foundations-labs')+'''</div></section><section class="manifesto" id="learning-lab"><div class="wrap split"><div><span class="eyebrow">For enrolled learners</span><h2>Your learning<br>ecosystem.</h2></div><div><h3>CVI Learning Lab</h3><p>Continue games, knowledge checks, flashcards, and reference practice in the CVI Learning Lab.</p><a class="button" href="https://learninglab.cybervisionariesinstitute.org">Open Learning Lab ↗</a><p>Sign in with your existing CVI Learning Lab account. Access follows your program enrollment.</p><h3>Lab Portal & submissions</h3><p>Use your cohort’s official links for assignments, due dates, VM access, and submissions. These services retain their own sign-in and access requirements.</p><p class="note">Use the Learning Lab link above for study and practice. Find Lab Portal and submission links in your cohort space.</p></div></div></section>'''
body['about']=intro('About CyberVisionaries Institute','Capability grows<br>through practice.','CVI connects structured learning, mentorship, and applied technical experience to help learners build demonstrable cybersecurity skills.')+'''<section class="wrap section top-less split about-split"><img class="office-portrait" src="/assets/nova-office.webp" alt="Nova in the CyberVisionaries Institute office beside CVI signage" loading="lazy"><div><span class="eyebrow">Our approach</span><h2>Learn with purpose.<br>Build with confidence.</h2><p>CyberVisionaries Institute develops learning experiences that help people understand technical concepts, apply them in context, and communicate what they have learned.</p><p>CyberFoundations introduces the systems and security concepts that form a technical foundation. The PKI Career Pathway develops specialized knowledge of digital trust and enterprise certificate operations.</p><p>Clear instructions, predictable structure, and approachable explanations support learners with different backgrounds and ways of learning.</p><a class="button" href="/resources/">Explore CVI resources ↗</a></div></section>'''
