 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | CVI Technology & Innovation Hub</title><meta name="description" content="Explore CyberVisionaries Institute’s CyberFoundations and PKI pathways, applied learning, and official technical resources."><meta name="theme-color" content="#0b0d15"><link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script></head><body class="page-{slug or 'home'}"><a class="skip" href="#main">Skip to content</a><header class="header"><a class="wordmark" href="/" aria-label="CyberVisionaries Institute home"><span class="official-logo"><img src="/assets/cvi-logo.png" alt="CyberVisionaries Institute"></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span>+</span></button><nav id="navigation" aria-label="Main navigation">{nav}</nav></header><main id="main">{body[slug]}</main><section class="bottom-cta wrap"><span class="eyebrow">Keep exploring</span><h2>Your next chapter<br>starts with <em>curiosity.</em></h2><a class="button" href="/{'resources/' if slug=='cyberfoundations' or slug=='pki' else 'cyberfoundations/'}">{'Explore resources' if slug in ['cyberfoundations','pki'] else 'Explore CyberFoundations'} ↗</a></section><footer class="wrap footer"><div><span class="official-logo footer-logo"><img src="/assets/cvi-logo.png" alt="CyberVisionaries Institute"></span><p>Technology & Innovation Hub</p></div><div><a href="{gh}">GitHub organization ↗</a><p>© 2026 CyberVisionaries Institute. All rights reserved.</p><small>CVI branding, characters, and original artwork remain CVI intellectual property.</small></div></footer></body></html>'''
